import fs from 'node:fs';import path from 'node:path';import {spawnSync}from'node:child_process';import {performance}from'node:perf_hooks';import {createHash}from'node:crypto';
import {payloadHash}from'../execution/ledger.mjs';import {createDualNoPairStateV2,advanceDualNoPairV2,dualNoPairReportV2}from'../live-paper/dual-no-pair-paper-v2.mjs';
