const need=(ok,c)=>{if(!ok)throw Error('DUAL_NO_RUST_'+c)},sha=b=>createHash('sha256').update(b).digest('hex');
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),pointer=JSON.parse(fs.readFileSync(path.join(rt,'dual-no-pair-v2-active.json'))),dir=path.join(rt,'dual-no-pair-v2-cohorts',pointer.cohort),bank=JSON.parse(fs.readFileSync(path.join(dir,'bank.json'))),journal=path.join(dir,'journal.jsonl');
const binary=path.resolve('backend-rust/dual-no-engine/target/release/baal-dual-no-engine.exe'),tool=path.join(process.env.LOCALAPPDATA,'SigTradingCup/rust-toolchain/rustup/toolchains/stable-x86_64-pc-windows-gnullvm/bin');
const run=requests=>{const input=requests.map(x=>JSON.stringify(x)+'\n').join(''),t=performance.now(),p=spawnSync(binary,[],{input,encoding:'utf8',maxBuffer:256*1024*1024,env:{...process.env,PATH:tool+';'+process.env.PATH}});need(p.status===0,'PROCESS_'+p.stderr);const wallMs=performance.now()-t,results=p.stdout.trim().split('\n').map(x=>JSON.parse(x));need(results.length===requests.length,'RESPONSES');for(const r of results)need(!r.error,'RESPONSE_'+r.error);return{results,wallMs};};
let records=[],prev='',seq=0;const end=sealedEnd(journal),digest=createHash('sha256');for(const line of journalLines(journal,{endByte:end})){digest.update(line+'\n');const row=JSON.parse(line),{hash,...body}=row;need(row.sequence===++seq&&row.previous===prev&&sha(JSON.stringify(body))===hash,'JOURNAL_CHAIN');prev=hash;records.push(row);}
