const base=Date.parse(bank.cutoff),at=n=>new Date(base+n).toISOString(),legIds=bank.review.legs.map(x=>x.exchangeId);
function fakeBook(id,clock,patch={}){const leg=bank.review.legs.find(x=>x.exchangeId===id);return{marketId:leg.marketId,exchangeId:id,requestStartedAt:at(clock),receivedAt:at(clock+100),versionKey:clock+':'+at(clock+100),publicationSequence:clock,publicationHash:'a'.repeat(64),bids:[{price:id===legIds[0]?'0.880000':'0.145000',quantity:1000}],asks:[{price:id===legIds[0]?'0.890000':'0.155000',quantity:1000}],...patch};}
function fakeEvent(id,clock,otherClock,patch={},accountPatch){const book=fakeBook(id,clock,patch),other=otherClock===null?null:fakeBook(legIds.find(x=>x!==id),otherClock);return{kind:'book',availableAt:book.receivedAt,book,pairBooks:[book,other].filter(Boolean),accountEligibility:accountPatch===undefined?{schemaVersion:1,positionsAt:at(Math.min(clock,otherClock??clock)-100),ordersAt:at(Math.min(clock,otherClock??clock)-100),excludedExchangeIds:[]}:accountPatch,admission:{positiveConditionalCapacity:true}};}
const prefix=[fakeEvent(legIds[1],1100,1000),fakeEvent(legIds[1],11000,10000)],first=[...prefix,fakeEvent(legIds[0],14000,11000)],held=[...first,fakeEvent(legIds[1],18000,14000)];
const scenarios=[['funded_later_requests',held],['insufficient_fractional_depth',[...prefix,fakeEvent(legIds[0],14000,11000,{bids:[{price:'0.880000',quantity:99}]})]],['fixed_limit_failed_hedge',[...first,fakeEvent(legIds[1],18000,14000,{bids:[{price:'0.130000',quantity:1000}]}),{kind:'boundary',availableAt:at(19000)}]],['epoch_or_stop_preserves_orphan',[...first,{kind:'boundary',availableAt:at(19000)},fakeEvent(legIds[0],22000,null),fakeEvent(legIds[0],25000,null)]],['expired_review_preserves_orphan',[...first,fakeEvent(legIds[1],4000000,3995000)]],['held_inventory_not_calendar_payout',[...held,{kind:'boundary',availableAt:at(4000000)}]],['missing_account_blocks_hedge',[...first,fakeEvent(legIds[1],18000,14000,{},null)]],['excluded_leg_blocks_hedge',[...first,fakeEvent(legIds[1],18000,14000,{}, {schemaVersion:1,positionsAt:at(13900),ordersAt:at(13900),excludedExchangeIds:[legIds[0]]})]],['future_account_blocks_hedge',[...first,fakeEvent(legIds[1],18000,14000,{}, {schemaVersion:1,positionsAt:at(19000),ordersAt:at(19000),excludedExchangeIds:[]})]],['holding_limit_requires_actual_exit',[...held,fakeEvent(legIds[1],3024020000,3024019000),fakeEvent(legIds[1],3024024000,3024019000),fakeEvent(legIds[0],3024028000,3024024000)]]];
const correctRequests=[],correctExpected=[];for(const[name,events]of scenarios){let q=createDualNoPairStateV2(bank);correctRequests.push({op:'init',bank});correctExpected.push({state:q});for(const e of events){q=advanceDualNoPairV2(q,e,bank);correctRequests.push({op:'advance',event:e},{op:'report',at:e.availableAt});correctExpected.push({state:q},{report:dualNoPairReportV2(q,bank,e.availableAt)});}failures.push({name,events:events.length,finalStateHash:payloadHash(q),realizedPnl:q.realizedPnl,exactParity:true,syntheticCorrectnessOnly:true});}const correctness=run(correctRequests);correctness.results.forEach((v,i)=>need(payloadHash(v)===payloadHash(correctExpected[i]),'CORRECTNESS_PARITY_'+i));
const events=records.slice(1).map(x=>x.event),repeat=20,benchRequests=Array.from({length:repeat},()=>[{op:'init',bank},{op:'batch',events}]).flat();let t=performance.now();for(let i=0;i<repeat;i++){let q=createDualNoPairStateV2(bank);for(const e of events)q=advanceDualNoPairV2(q,e,bank);need(payloadHash(q)===payloadHash(s),'JS_BENCH');}const nodeMs=performance.now()-t,rust=run(benchRequests);for(let i=1;i<rust.results.length;i+=2)need(payloadHash(rust.results[i].state)===payloadHash(s),'BATCH_PARITY');
const out={schemaVersion:1,at:new Date().toISOString(),mode:'isolated_generic_rust_dual_no_engine',cohort:bank.name,bankHash:payloadHash(bank),binaryHash:sha(fs.readFileSync(binary)),originalSealedJournal:{bytes:end,records:records.length,sha256:digest.digest('hex'),lastSequence:seq,lastHash:prev},fullStateAndReportParity:{responses:expected.length,exact:true,finalStateHash:payloadHash(s)},failureContinuations:failures,benchmark:{repeats:repeat,events:events.length*repeat,nodeMs,rustIncludingOneSpawnSerializationMs:rust.wallMs,speedup:nodeMs/rust.wallMs,singleLongLivedJsonlWorker:true,noPerBookProcessSpawn:true},report:dualNoPairReportV2(s,bank,s.lastAt),runtimeChanged:false,networkRequests:0,contestOrders:0,profitabilityEstablished:false,limitations:['Parity and throughput are correctness/performance evidence, not proof of a profitable strategy.','Original sealed journal events preserve later receipts, causal eligibility and attributed liabilities.','Rust bank validation is cached per batch; integer funded-state checks run after every event.','Existing frozen cohorts and collectors remain on their original engine. Production adoption needs a separately bound continuation.']};fs.writeFileSync('data/dual-no-rust-benchmark-20261005.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({records:records.length,responses:expected.length,nodeMs,rustMs:rust.wallMs,speedup:nodeMs/rust.wallMs,exactParity:true,realized:s.realizedPnl}));
